import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@DisplayName("70/69_same_tree")
class SolutionTest {

    @Test
    void shouldAcceptIdenticalTrees() {

        Completed solution = new Completed();

        TreeNode p = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        TreeNode q = new TreeNode(1, new TreeNode(2), new TreeNode(3));

        assertTrue(solution.isSameTree(p, q));
    }

    @Test
    void shouldRejectDifferentStructure() {

        Completed solution = new Completed();

        TreeNode p = new TreeNode(1, new TreeNode(2), null);
        TreeNode q = new TreeNode(1, null, new TreeNode(2));

        assertFalse(solution.isSameTree(p, q));
    }

    @Test
    void shouldRejectDifferentValues() {

        Completed solution = new Completed();

        TreeNode p = new TreeNode(1, new TreeNode(2), new TreeNode(1));
        TreeNode q = new TreeNode(1, new TreeNode(1), new TreeNode(2));

        assertFalse(solution.isSameTree(p, q));
    }

    @Test
    void shouldAcceptTwoEmptyTrees() {

        Completed solution = new Completed();

        assertTrue(solution.isSameTree(null, null));
    }

    @Test
    void shouldRejectOneEmptyTree() {

        Completed solution = new Completed();

        assertFalse(solution.isSameTree(new TreeNode(1), null));
    }
}
